// Server-side bridge to Nuro Platform's Recruitment API.
//
// The browser only ever calls this site's own /api/careers/* routes. These
// run on Vercel's servers, add the secret X-Website-Key and forward to Nuro
// Platform, so the key never reaches the browser and the platform API isn't
// callable by the public at all.

// Offer slugs are generated by the platform from titles: lowercase letters,
// digits and hyphens. Anything else is rejected here so a crafted "slug"
// can never point the proxy at a different platform URL.
const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/

export function assertSlug(slug) {
  if (typeof slug !== 'string' || slug.length > 160 || !SLUG.test(slug)) {
    throw createError({ statusCode: 404, statusMessage: 'Not found' })
  }
  return slug
}

// The visitor's IP, so the platform can rate-limit per person (otherwise it
// would only ever see Vercel's IPs). On Vercel, x-real-ip / x-forwarded-for
// are set by Vercel's edge, not by the client.
function visitorIp(event) {
  return getHeader(event, 'x-real-ip') || getRequestIP(event, { xForwardedFor: true }) || ''
}

/**
 * Call the platform. Returns { status, data }. Only statuses the website
 * knows how to show are passed through; anything else (401 = key mismatch,
 * 5xx, network error) is logged here and surfaced as a generic 502, so no
 * internal detail leaks to the browser.
 */
export async function platformFetch(event, path, options = {}, passthrough = [200]) {
  const { platformApiUrl, platformApiKey } = useRuntimeConfig(event)

  if (!platformApiKey) {
    console.error('[careers] NUXT_PLATFORM_API_KEY is not set')
    throw createError({ statusCode: 502, statusMessage: 'Service unavailable' })
  }

  let res
  try {
    res = await $fetch.raw(`${platformApiUrl}/api/recruitment${path}`, {
      ...options,
      headers: {
        Accept: 'application/json',
        'X-Website-Key': platformApiKey,
        'X-Client-IP': visitorIp(event),
        ...(options.headers || {}),
      },
      timeout: 15000,
      ignoreResponseError: true,
      retry: 0,
    })
  } catch (e) {
    console.error('[careers] platform unreachable:', e?.message)
    throw createError({ statusCode: 502, statusMessage: 'Service unavailable' })
  }

  if (!passthrough.includes(res.status)) {
    console.error(`[careers] platform answered ${res.status} for ${path}`)
    throw createError({ statusCode: 502, statusMessage: 'Service unavailable' })
  }

  return { status: res.status, data: res._data }
}
